	    LoanTransaction entity = new LoanTransaction();
            entity.setLoanTransactionId( event.getLoanTransactionId() );
            entity.setTransactionId( event.getTransactionId() );
            entity.setAmount( event.getAmount() );
            entity.setPostingDate( event.getPostingDate() );
            entity.setType( event.getType() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
